1	package org.springframework.samples.petclinic.security;
2	
3	import org.springframework.beans.factory.annotation.Autowired;
4	import org.springframework.security.core.authority.SimpleGrantedAuthority;
5	import org.springframework.security.core.userdetails.User;
6	import org.springframework.security.core.userdetails.UserDetails;
7	import org.springframework.security.core.userdetails.UserDetailsService;
8	import org.springframework.security.core.userdetails.UsernameNotFoundException;
9	import org.springframework.security.crypto.password.PasswordEncoder;
10	import org.springframework.stereotype.Service;
11	
12	import java.util.Collections;
13	
14	@Service
15	public class CustomUserDetailsService implements UserDetailsService {
16	
17		@Autowired
18		private PasswordEncoder passwordEncoder;
19	
20		@Override
21		public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
22			// 간단한 사용자 인증을 위해 하드코딩된 사용자 정보를 사용
23			// 실제 프로덕션에서는 데이터베이스에서 사용자 정보를 조회해야 합니다
24			if ("admin".equals(username)) {
25				return new User("admin", passwordEncoder.encode("password"),
26						Collections.singletonList(new SimpleGrantedAuthority("ROLE_USER")));
27			}
28			else if ("user".equals(username)) {
29				return new User("user", passwordEncoder.encode("password"),
30						Collections.singletonList(new SimpleGrantedAuthority("ROLE_USER")));
31			}
32			else {
33				throw new UsernameNotFoundException("User not found: " + username);
34			}
35		}
36	
37	}
