package org.springframework.samples.petclinic.blackbox;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController
 * (src/main/java/org/springframework/samples/petclinic/security/AuthController.java)
 * @target-api POST /api/auth/login
 *
 * Auth analysis (analyze-auth-flow, .nimbus/artifacts/auth-flow/AuthController_login.json):
 * /api/auth/** is permitAll in SecurityConfig, so no Authorization header is required for this
 * endpoint itself.
 *
 * Dependency analysis (dependency-tree, detect-external-calls):
 * login() has no DB table access and no outbound HTTP calls - CustomUserDetailsService returns
 * two hardcoded users ("admin"/"password", "user"/"password"). No setup/teardown SQL and no
 * WireMock stubs are required for this endpoint.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiAuthLoginBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/api/auth/login";

	private static final String INVALID_CREDENTIALS_BODY = "{\"error\":\"Invalid username or password\"}";

	private String testId(TestInfo info) {
		return String.format("T%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_login_admin_success - admin/password 로그인 성공")
	void NTC_login_admin_success() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("type", equalTo("Bearer"))
			.body("username", equalTo("admin"))
			.body("expiresIn", equalTo(86400))
			.body("token", matchesPattern("^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$"));
	}

	@Test
	@DisplayName("NTC_login_user_success - user/password 로그인 성공")
	void NTC_login_user_success() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"user\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("type", equalTo("Bearer"))
			.body("username", equalTo("user"))
			.body("expiresIn", equalTo(86400))
			.body("token", matchesPattern("^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$"));
	}

	@Test
	@DisplayName("NTC_login_success_jwtPayloadContainsUsername - 발급된 JWT payload의 sub 클레임이 로그인한 username과 일치")
	void NTC_login_success_jwtPayloadContainsUsername() {
		String token = given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(200)
			.extract().path("token");

		String[] parts = token.split("\\.");
		assertTrue(parts.length == 3, "JWT must have 3 dot-separated segments");
		String payloadJson = new String(Base64.getUrlDecoder().decode(parts[1]), StandardCharsets.UTF_8);
		assertTrue(payloadJson.contains("\"sub\":\"admin\""),
				"JWT payload must contain sub claim equal to 'admin', got: " + payloadJson);
	}

	// ===================== VTC (username RED param mutations) =====================

	@Test
	@DisplayName("VTC_username_NULL - username 파라미터 누락(null)")
	void VTC_username_NULL(TestInfo info) {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":null,\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("VTC_username_EMPTY - username 빈 값 전송")
	void VTC_username_EMPTY(TestInfo info) {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("VTC_username_WHITE_SPACE - username 공백만 전송")
	void VTC_username_WHITE_SPACE(TestInfo info) {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"   \",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("VTC_username_SPECIAL_CHAR - username SQL injection 문자열 전송")
	void VTC_username_SPECIAL_CHAR(TestInfo info) {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"'; DROP TABLE owners--\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	// ===================== ATC (business exception) =====================

	@Test
	@DisplayName("ATC_username_noData - DB(하드코딩 사용자 목록)에 존재하지 않는 username")
	void ATC_username_noData(TestInfo info) {
		String unknownUsername = "nouser_" + testId(info);
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"" + unknownUsername + "\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("ATC_code404 - 존재하는 username(admin)에 잘못된 password로 UsernameNotFoundException/BadCredentials 분기 유발")
	void ATC_code404(TestInfo info) {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"wrong_password_" + testId(info) + "\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	// ===================== API-level VTC (generate-vtc-from-red-params) =====================

	@Test
	@DisplayName("VTC_api_emptyBody - 요청 body 없이 전송")
	void VTC_api_emptyBody() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400);
	}

	@Test
	@DisplayName("VTC_api_overflow - 과도하게 큰 username 전송")
	void VTC_api_overflow() {
		String oversized = "A".repeat(10240);
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"" + oversized + "\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("VTC_api_xss - XSS 공격 문자열 전송")
	void VTC_api_xss() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"username\":\"<script>alert(1)</script>\",\"password\":\"password\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("VTC_api_badHeader - 지원하지 않는 Content-Type(application/xml) 전송 시 415")
	void VTC_api_badHeader() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType("application/xml")
			.accept(ContentType.JSON)
			.body("<xml>invalid</xml>")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(415);
	}

	@Test
	@DisplayName("VTC_api_structureTamper - 요청 스키마에 없는 필드만 삽입(username/password 누락)")
	void VTC_api_structureTamper() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.accept(ContentType.JSON)
			.body("{\"__injected__\":true,\"nested\":{\"deep\":1}}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.body(equalTo(INVALID_CREDENTIALS_BODY));
	}

	@Test
	@DisplayName("VTC_api_wrongMethod - GET으로 호출 시 405 Method Not Allowed")
	void VTC_api_wrongMethod() {
		given().log().all()
			.baseUri(BASE_URL)
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(405);
	}

}

