			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
	}

	private static void deleteOwnerById(int id) throws Exception {
		try (Connection conn = getDbConnection();
				PreparedStatement ps = conn.prepareStatement("DELETE FROM owners WHERE id = ?")) {
			ps.setInt(1, id);
			ps.executeUpdate();
		}
