		String telephone = uniqueTelephone(info);
		executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));

		String body = """
				{"firstName":"Alice","lastName":"Wonderland","address":"1 Rabbit Hole","city":"Madison","telephone":"%s"}
				"""
			.formatted(telephone);

		Integer id = null;
		try {
			id = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("firstName", equalTo("Alice"))
				.body("lastName", equalTo("Wonderland"))
				.body("address", equalTo("1 Rabbit Hole"))
				.body("city", equalTo("Madison"))
				.body("telephone", equalTo(telephone))
				.body("id", notNullValue())
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT first_name, last_name, address, city, telephone FROM owners WHERE id = ?")) {
				ps.setInt(1, id);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next(), "created owner row must exist in DB");
				assertEquals("Alice", rs.getString("first_name"));
				assertEquals("Wonderland", rs.getString("last_name"));
				assertEquals("1 Rabbit Hole", rs.getString("address"));
				assertEquals("Madison", rs.getString("city"));
				assertEquals(telephone, rs.getString("telephone"));
			}
		}
		finally {
			if (id != null) {
				deleteOwnerById(id);
			}
			executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		}
	}

	@Test
	@DisplayName("NTC_createOwner_success_differentData - 다른 값 조합으로 생성 성공 (201)")
	void NTC_createOwner_success_differentData(TestInfo info) throws Exception {
		String telephone = uniqueTelephone(info);
		executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));

		String body = """
				{"firstName":"Bob","lastName":"Builder","address":"99 Construction Way","city":"Waunakee","telephone":"%s"}
				"""
			.formatted(telephone);

		Integer id = null;
		try {
			id = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("firstName", equalTo("Bob"))
				.body("lastName", equalTo("Builder"))
				.body("address", equalTo("99 Construction Way"))
				.body("city", equalTo("Waunakee"))
				.body("telephone", equalTo(telephone))
				.extract().path("id");
		}
		finally {
			if (id != null) {
				deleteOwnerById(id);
			}
			executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		}
	}

	@Test
	@DisplayName("NTC_createOwner_success_petsFieldEmptyByDefault - pets는 setter가 없어 응답에 항상 빈 배열")
	void NTC_createOwner_success_petsFieldEmptyByDefault(TestInfo info) throws Exception {
		String telephone = uniqueTelephone(info);
		executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));

		String body = """
				{"firstName":"Carol","lastName":"Danvers","address":"1 Avenger Way","city":"Monona","telephone":"%s","pets":[{"name":"ShouldBeIgnored"}]}
				"""
			.formatted(telephone);

		Integer id = null;
		try {
			id = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("firstName", equalTo("Carol"))
				.body("pets.size()", equalTo(0))
				.extract().path("id");
		}
		finally {
			if (id != null) {
				deleteOwnerById(id);
			}
			executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		}
	}

