		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("null")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(500);
	}

	@Test
