	void VTC_owner_EMPTY() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("{}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(500);
	}

	@Test
	@DisplayName("VTC_owner_WHITE_SPACE - body가 공백 문자열뿐 -> 유효한 JSON이 아니므로 400")
	void VTC_owner_WHITE_SPACE() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("   ")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400);
	}

	@Test
	@DisplayName("VTC_owner_SPECIAL_CHAR - firstName에 SQL injection 문자열 전송 -> PreparedStatement 바인딩으로 안전하게 리터럴 저장됨(201)")
	void VTC_owner_SPECIAL_CHAR(TestInfo info) throws Exception {
		String telephone = uniqueTelephone(info);
		executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		String injection = "'; DROP TABLE owners; --";

		String body = """
				{"firstName":"%s","lastName":"Injected","address":"1 Attack Rd","city":"Madison","telephone":"%s"}
				"""
			.formatted(injection, telephone);

		Integer id = null;
		try {
			id = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("firstName", equalTo(injection))
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) AS cnt FROM owners")) {
				ResultSet rs = ps.executeQuery();
				rs.next();
				assertTrue(rs.getInt("cnt") > 0, "owners table must still exist and contain rows (no injection occurred)");
			}
		}
		finally {
			if (id != null) {
				deleteOwnerById(id);
			}
			executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		}
	}

	// ===================== ATC (business exception) =====================

	@Test
	@DisplayName("ATC_owner_noData - telephone이 \\d{10} 패턴 위반(문자 포함) -> @Pattern 위반 -> ConstraintViolationException -> 500")
	void ATC_owner_noData(TestInfo info) {
		String body = """
				{"firstName":"Dave","lastName":"Grohl","address":"1 Rock Rd","city":"Madison","telephone":"NOT_A_PHONE"}
				""";
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body(body)
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(500);
	}

	@Test
	@DisplayName("ATC_code400 - 문법적으로 깨진 JSON 전송 -> HttpMessageNotReadableException -> 400")
	void ATC_code400() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("{\"firstName\":\"Eve\", \"lastName\": ")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400);
	}

	// ===================== API-level VTC =====================

	@Test
	@DisplayName("VTC_api_emptyBody - 요청 body 없이 전송 -> HttpMessageNotReadableException -> 400")
