	@DisplayName("VTC_api_overflow - address에 10KB 문자열 전송 -> varchar(255) 초과 -> DataIntegrityViolationException -> 500")
	void VTC_api_overflow(TestInfo info) throws Exception {
		String telephone = uniqueTelephone(info);
		executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		String oversized = "A".repeat(10240);

		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"firstName\":\"Frank\",\"lastName\":\"Ocean\",\"address\":\"" + oversized
						+ "\",\"city\":\"Madison\",\"telephone\":\"" + telephone + "\"}")
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		}
	}

	@Test
	@DisplayName("VTC_api_xss - firstName에 XSS 스크립트 문자열 전송 -> 서버가 sanitize하지 않고 그대로 저장(201)")
	void VTC_api_xss(TestInfo info) throws Exception {
		String telephone = uniqueTelephone(info);
		executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		String xss = "<script>alert(1)</script>";

		Integer id = null;
		try {
			id = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"firstName\":\"" + xss
						+ "\",\"lastName\":\"Xss\",\"address\":\"1 Script St\",\"city\":\"Madison\",\"telephone\":\""
						+ telephone + "\"}")
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("firstName", equalTo(xss))
				.extract().path("id");
		}
		finally {
			if (id != null) {
				deleteOwnerById(id);
			}
			executeSqlTemplate("sql/post-owners-teardown.sql", Map.of("TELEPHONE", telephone));
		}
	}

	@Test
	@DisplayName("VTC_api_badHeader - 지원하지 않는 Content-Type(application/xml) 전송 -> 415")
	void VTC_api_badHeader() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType("application/xml")
			.body("<xml>invalid</xml>")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(415);
	}

	@Test
	@DisplayName("VTC_api_structureTamper - 알 수 없는 필드만 포함 -> 나머지 필드 null -> @NotBlank 위반 -> 500")
	void VTC_api_structureTamper() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("{\"__injected__\":true,\"nested\":{\"deep\":1}}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(500);
	}

	@Test
	@DisplayName("VTC_api_wrongMethod - 잘못된 HTTP 메서드(PATCH) 전송 -> 405 Method Not Allowed")
	void VTC_api_wrongMethod() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("{}")
		.when()
			.patch(API_PATH)
		.then().log().all()
			.statusCode(405);
	}

	// ===================== Auth =====================

	@Test
	@DisplayName("ATC_noAuthHeader - Authorization 헤더 없이 호출 -> 403 Forbidden")
	void ATC_noAuthHeader() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"firstName\":\"NoAuth\",\"lastName\":\"User\",\"address\":\"1 St\",\"city\":\"Madison\",\"telephone\":\"9999999999\"}")
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(403);
	}

}

