package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller OwnerRestController
 * (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api PUT /api/owners/{ownerId}
 *
 * Auth: /api/** requires a valid JWT (SecurityConfig). Token obtained via real
 * POST /api/auth/login (admin/password).
 *
 * updateOwner() logic (read directly from source):
 * 1. if (!ownerRepository.existsById(ownerId)) return 404
 * 2. owner.setId(ownerId)  <-- path variable id always overwrites any id in the request body
 * 3. ownerRepository.save(owner) -> 200 with saved owner
 *
 * Same Bean Validation caveat as createOwner: no @Valid on the controller method, but Hibernate's
 * automatic JPA Bean Validation (PreUpdate) still fires on save() because spring-boot-starter-validation
 * is on the classpath, so a ConstraintViolationException from @NotBlank/@Pattern surfaces as an
 * uncaught 500, not a 400.
 *
 * No outbound HTTP calls (detect-external-calls): no WireMock stubs required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class PutOwnersBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	private String testId(TestInfo info) {
		return String.format("T%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
	}

	/** Deterministic unique owner id per test method, disjoint from seed data (1-10) and from
	 * PostOwnersBlackBoxTest's id range (auto-generated, but always > 10). */
	private int ownerId(TestInfo info) {
		return 8_000_000 + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 900_000);
	}

	private String originalTelephone(TestInfo info) {
		return "8" + String.format("%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = PutOwnersBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (var entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	private void setupOwner(TestInfo info) {
		executeSqlTemplate("sql/put-owners-setup.sql",
				Map.of("OWNER_ID", String.valueOf(ownerId(info)), "ORIGINAL_TELEPHONE", originalTelephone(info)));
	}

	private void teardownOwner(TestInfo info) {
		executeSqlTemplate("sql/put-owners-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId(info))));
	}

	private static String obtainAdminToken() {
		return given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_updateOwner_success - 기존 owner를 새 값으로 갱신 성공 (200) 및 DB 반영 확인")
	void NTC_updateOwner_success(TestInfo info) throws Exception {
		int id = ownerId(info);
		setupOwner(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"firstName\":\"Updated\",\"lastName\":\"Name\",\"address\":\"New Address\",\"city\":\"NewCity\",\"telephone\":\"1234567890\"}")
			.when()
				.put("/api/owners/" + id)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(id))
				.body("firstName", equalTo("Updated"))
				.body("lastName", equalTo("Name"))
				.body("address", equalTo("New Address"))
				.body("city", equalTo("NewCity"))
				.body("telephone", equalTo("1234567890"));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn
						.prepareStatement("SELECT first_name, telephone FROM owners WHERE id = ?")) {
				ps.setInt(1, id);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals("Updated", rs.getString("first_name"));
				assertEquals("1234567890", rs.getString("telephone"));
			}
		}
		finally {
			teardownOwner(info);
		}
	}

	@Test
	@DisplayName("NTC_updateOwner_success_onlyTelephoneChanged - telephone만 다른 값으로 갱신 성공 (200)")
	void NTC_updateOwner_success_onlyTelephoneChanged(TestInfo info) throws Exception {
		int id = ownerId(info);
		setupOwner(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"firstName\":\"OrigFirst\",\"lastName\":\"OrigLast\",\"address\":\"Original Address\",\"city\":\"OriginalCity\",\"telephone\":\"5551234567\"}")
			.when()
				.put("/api/owners/" + id)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(id))
				.body("firstName", equalTo("OrigFirst"))
				.body("telephone", equalTo("5551234567"));
		}
		finally {
			teardownOwner(info);
		}
	}

	@Test
	@DisplayName("NTC_updateOwner_bodyIdIgnored_pathIdWins - body의 id 필드는 무시되고 path variable id가 사용됨")
	void NTC_updateOwner_bodyIdIgnored_pathIdWins(TestInfo info) throws Exception {
		int id = ownerId(info);
		setupOwner(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"id\":999999999,\"firstName\":\"IdOverride\",\"lastName\":\"Test\",\"address\":\"A\",\"city\":\"B\",\"telephone\":\"1112223333\"}")
			.when()
				.put("/api/owners/" + id)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(id))
				.body("firstName", equalTo("IdOverride"));
		}
		finally {
			teardownOwner(info);
		}
	}

	// ===================== VTC (owner RED param mutations) =====================

	@Test
	@DisplayName("VTC_owner_NULL - body가 JSON null -> owner.setId() NPE -> 500")
	void VTC_owner_NULL(TestInfo info) {
		int id = ownerId(info);
		setupOwner(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("null")
			.when()
				.put("/api/owners/" + id)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwner(info);
		}
	}

	@Test
	@DisplayName("VTC_owner_EMPTY - 빈 JSON 객체 -> 모든 @NotBlank 필드 위반 -> ConstraintViolationException -> 500")
	void VTC_owner_EMPTY(TestInfo info) {
		int id = ownerId(info);
		setupOwner(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{}")
			.when()
				.put("/api/owners/" + id)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwner(info);
		}
	}

	@Test
	@DisplayName("VTC_owner_WHITE_SPACE - body가 공백뿐 -> 유효한 JSON 아님 -> 400")
	void VTC_owner_WHITE_SPACE(TestInfo info) {
		int id = ownerId(info);
		setupOwner(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("   ")
			.when()
				.put("/api/owners/" + id)
			.then().log().all()
				.statusCode(400);
		}
		finally {
			teardownOwner(info);
		}
