				.body("lastName", equalTo("Name"))
				.body("address", equalTo("New Address"))
				.body("city", equalTo("NewCity"))
				.body("telephone", equalTo("1234567890"));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn
						.prepareStatement("SELECT first_name, telephone FROM owners WHERE id = ?")) {
