package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller PetRestController
 * (src/main/java/org/springframework/samples/petclinic/owner/PetRestController.java)
 * @target-api POST /api/pets
 *
 * Auth: /api/** requires a valid JWT. Token obtained via real POST /api/auth/login.
 *
 * createPet() logic (read directly from source):
 * - `ownerId` is an unannotated Integer method parameter with no other mapping annotation, so
 *   Spring MVC's default resolution treats it as a REQUIRED @RequestParam named "ownerId"
 *   (query string). Missing/non-numeric -> 400 (MissingServletRequestParameterException /
 *   MethodArgumentTypeMismatchException), confirmed by generate-vtc-from-red-params RED param
 *   analysis (ownerId flagged DB_WHERE).
 * - ownerRepository.findById(ownerId).isEmpty() -> 404 (real business branch).
 * - owner.addPet(pet) only appends the pet to the in-memory collection `if (pet.isNew())`, i.e.
 *   only when the request body's pet has NO "id" field. If the client supplies an "id", addPet()
 *   silently no-ops and the pet is NEVER persisted, yet the controller still returns 201 with the
 *   client-supplied body. This is a genuine (if surprising) business branch, verified via JDBC.
 * - pets.type_id column is NOT NULL with an FK to `types`; Pet.type has no cascade, so Hibernate
 *   writes the FK from the given type id without loading/persisting it. A non-existent type id
 *   causes an FK violation (500); a null type causes a NOT NULL violation (500).
 * - Pet.name is @NotBlank (NamedEntity) - Hibernate's automatic Bean Validation on persist
 *   (spring-boot-starter-validation is on the classpath) throws ConstraintViolationException,
 *   uncaught -> 500, since createPet has no @Valid and there is no @ControllerAdvice.
 *
 * No outbound HTTP calls (detect-external-calls): no WireMock stubs required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class PostPetsBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static final String API_PATH = "/api/pets";

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	private String testId(TestInfo info) {
		return String.format("T%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
	}

	/** Deterministic unique owner id per test method (disjoint from owner-endpoint id ranges). */
	private int ownerId(TestInfo info) {
		return 7_000_000 + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 900_000);
	}

	private String ownerTelephone(TestInfo info) {
		return "7" + String.format("%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = PostPetsBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (var entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	private void setupOwner(TestInfo info) {
		executeSqlTemplate("sql/post-pets-setup.sql",
				Map.of("OWNER_ID", String.valueOf(ownerId(info)), "TELEPHONE", ownerTelephone(info)));
	}

	private void teardownOwner(TestInfo info) {
		executeSqlTemplate("sql/post-pets-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId(info))));
	}

	private static String obtainAdminToken() {
		return given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
	}

	private static int petCountForOwner(int ownerId) throws Exception {
		try (Connection conn = getDbConnection();
				PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) AS cnt FROM pets WHERE owner_id = ?")) {
			ps.setInt(1, ownerId);
			ResultSet rs = ps.executeQuery();
			rs.next();
			return rs.getInt("cnt");
		}
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_createPet_success - 유효한 pet 데이터로 생성 성공 (201) 및 DB 반영 확인")
	void NTC_createPet_success(TestInfo info) throws Exception {
		int oid = ownerId(info);
		setupOwner(info);
		try {
			int petId = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.queryParam("ownerId", oid)
				.body("{\"name\":\"Fluffy\",\"birthDate\":\"2020-01-01\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("name", equalTo("Fluffy"))
				.body("birthDate", equalTo("2020-01-01"))
				.body("type.id", equalTo(1))
				.body("id", notNullValue())
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT name, birth_date, type_id, owner_id FROM pets WHERE id = ?")) {
				ps.setInt(1, petId);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next(), "created pet row must exist in DB");
				assertEquals("Fluffy", rs.getString("name"));
				assertEquals("2020-01-01", rs.getString("birth_date"));
				assertEquals(1, rs.getInt("type_id"));
				assertEquals(oid, rs.getInt("owner_id"));
			}
		}
		finally {
			teardownOwner(info);
		}
	}

	@Test
	@DisplayName("NTC_createPet_success_differentType - 다른 type(dog)으로 생성 성공 (201)")
