			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("name", equalTo("Ghost"))
				.body("birthDate", equalTo(null))
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT birth_date FROM pets WHERE id = ?")) {
				ps.setInt(1, petId);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals(null, rs.getString("birth_date"));
			}
		}
		finally {
			teardownOwner(info);
		}
	}

	// ===================== business branch: id-in-body silently ignored =====================

	@Test
	@DisplayName("ATC_petIdInBody_silentlyIgnored - body에 id 포함 시 addPet()이 no-op -> 201 응답이지만 실제로는 저장되지 않음")
	void ATC_petIdInBody_silentlyIgnored(TestInfo info) throws Exception {
		int oid = ownerId(info);
		setupOwner(info);
		try {
			assertEquals(0, petCountForOwner(oid));

			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.queryParam("ownerId", oid)
				.body("{\"id\":123456789,\"name\":\"Ghostly\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
			.when()
				.post(API_PATH)
			.then().log().all()
				.statusCode(201)
				.body("name", equalTo("Ghostly"));

			assertEquals(0, petCountForOwner(oid), "pet with a client-supplied id must NOT be persisted (addPet() no-op)");
		}
		finally {
			teardownOwner(info);
		}
	}

