package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller PetRestController
 * (src/main/java/org/springframework/samples/petclinic/owner/PetRestController.java)
 * @target-api PUT /api/pets/{petId}
 *
 * Auth: /api/** requires a valid JWT. Token obtained via real POST /api/auth/login.
 *
 * updatePet() logic (read directly from source):
 * - Iterates ownerRepository.findAll(), calls owner.getPet(petId); if no owner has a pet with
 *   that id -> 404.
 * - When found: existingPet.setName(pet.getName()); existingPet.setBirthDate(pet.getBirthDate());
 *   existingPet.setType(pet.getType()) - ALL THREE fields are unconditionally overwritten from the
 *   request body, even when a field is absent/null in the JSON (a "partial" update body nulls out
 *   the other fields). name is @NotBlank (Bean Validation fires on save() via Hibernate's
 *   automatic JPA integration, since no @Valid is used but spring-boot-starter-validation is on
 *   the classpath); type_id is NOT NULL at the DB level with no Bean Validation annotation, so a
 *   null type surfaces only as a DataIntegrityViolationException (500), not a validation error.
 * - The `id` field inside the request body pet is never read by updatePet() - only the path
 *   variable petId identifies which pet to update.
 *
 * No outbound HTTP calls (detect-external-calls): no WireMock stubs required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class PutPetsBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	private int ownerId(TestInfo info) {
		return 6_000_000 + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 500_000);
	}

	private int petId(TestInfo info) {
		return 6_500_000 + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 500_000);
	}

	private String ownerTelephone(TestInfo info) {
		return "6" + String.format("%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = PutPetsBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (var entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	private void setupOwnerAndPet(TestInfo info) {
		executeSqlTemplate("sql/put-pets-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId(info)), "PET_ID",
				String.valueOf(petId(info)), "TELEPHONE", ownerTelephone(info)));
	}

	private void teardownOwnerAndPet(TestInfo info) {
		executeSqlTemplate("sql/put-pets-teardown.sql",
				Map.of("OWNER_ID", String.valueOf(ownerId(info)), "PET_ID", String.valueOf(petId(info))));
	}

	private static String obtainAdminToken() {
		return given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_updatePet_success - 기존 pet을 새 값으로 갱신 성공 (200) 및 DB 반영 확인")
	void NTC_updatePet_success(TestInfo info) throws Exception {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\":\"UpdatedPet\",\"birthDate\":\"2021-05-05\",\"type\":{\"id\":2,\"name\":\"dog\"}}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(pid))
				.body("name", equalTo("UpdatedPet"))
				.body("birthDate", equalTo("2021-05-05"))
				.body("type.id", equalTo(2));

			try (Connection conn = getDbConnection(); PreparedStatement ps = conn
				.prepareStatement("SELECT name, birth_date, type_id FROM pets WHERE id = ?")) {
				ps.setInt(1, pid);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals("UpdatedPet", rs.getString("name"));
				assertEquals("2021-05-05", rs.getString("birth_date"));
				assertEquals(2, rs.getInt("type_id"));
			}
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("NTC_updatePet_success_differentType - 다른 type(lizard)으로 갱신 성공 (200)")
	void NTC_updatePet_success_differentType(TestInfo info) throws Exception {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\":\"OrigPetName\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":3,\"name\":\"lizard\"}}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(pid))
				.body("type.id", equalTo(3));
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("NTC_updatePet_bodyIdIgnored_pathIdWins - body의 id 필드는 무시되고 path variable petId가 사용됨")
	void NTC_updatePet_bodyIdIgnored_pathIdWins(TestInfo info) throws Exception {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"id\":999999999,\"name\":\"IdOverrideTest\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(pid))
				.body("name", equalTo("IdOverrideTest"));
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	// ===================== business branch: partial body nulls other fields =====================

	@Test
	@DisplayName("VTC_pet_partialUpdate_nullsOtherFields - name만 전송 -> birthDate/type이 null로 덮어써짐 -> type_id NOT NULL 위반 -> 500")
	void VTC_pet_partialUpdate_nullsOtherFields(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\":\"OnlyName\"}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	// ===================== VTC (pet RED param mutations) =====================

	@Test
	@DisplayName("VTC_pet_NULL - body가 JSON null -> pet.getName() NPE -> 500")
	void VTC_pet_NULL(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("null")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("VTC_pet_EMPTY - 빈 JSON 객체 -> name null로 덮어써짐 -> @NotBlank 위반 -> 500")
	void VTC_pet_EMPTY(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("VTC_pet_WHITE_SPACE - body가 공백뿐 -> 유효한 JSON 아님 -> 400")
	void VTC_pet_WHITE_SPACE(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("   ")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(400);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("VTC_pet_SPECIAL_CHAR - name에 SQL injection 문자열 -> PreparedStatement로 안전하게 리터럴 저장 (200)")
	void VTC_pet_SPECIAL_CHAR(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		String injection = "'; DROP TABLE pets; --";
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\":\"" + injection + "\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(200)
				.body("name", equalTo(injection));
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	// ===================== VTC (petId path-variable mutations) =====================

	@Test
	@DisplayName("VTC_petId_INVALID_FORMAT - petId=\"abc\" (숫자 아님) -> MethodArgumentTypeMismatchException -> 400")
	void VTC_petId_INVALID_FORMAT() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("{\"name\":\"X\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
		.when()
			.put("/api/pets/abc")
		.then().log().all()
			.statusCode(400);
	}

	// ===================== ATC (business exception) =====================

	@Test
	@DisplayName("ATC_petId_noData - 존재하지 않는 petId -> 어느 owner에도 해당 pet 없음 -> 404 Not Found")
	void ATC_petId_noData(TestInfo info) {
		int nonExistentPetId = petId(info) + 1; // never inserted by setupOwnerAndPet
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.contentType(ContentType.JSON)
			.body("{\"name\":\"X\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
		.when()
			.put("/api/pets/" + nonExistentPetId)
		.then().log().all()
			.statusCode(404);
	}

	@Test
	@DisplayName("ATC_typeId_noData - 존재하지 않는 type id -> FK 제약 위반(types) -> 500")
	void ATC_typeId_noData(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\":\"X\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":999999,\"name\":\"unknown\"}}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("ATC_code400 - 문법적으로 깨진 JSON 전송 -> HttpMessageNotReadableException -> 400")
	void ATC_code400(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\": ")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(400);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	// ===================== API-level VTC =====================

	@Test
	@DisplayName("VTC_api_emptyBody - 요청 body 없이 전송 -> 400")
	void VTC_api_emptyBody(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(400);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("VTC_api_overflow - name에 10KB 문자열 -> varchar(30) 초과 -> DataIntegrityViolationException -> 500")
	void VTC_api_overflow(TestInfo info) {
		int pid = petId(info);
		setupOwnerAndPet(info);
		String oversized = "A".repeat(10240);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + obtainAdminToken())
				.contentType(ContentType.JSON)
				.body("{\"name\":\"" + oversized + "\",\"birthDate\":\"2018-01-01\",\"type\":{\"id\":1,\"name\":\"cat\"}}")
			.when()
				.put("/api/pets/" + pid)
			.then().log().all()
				.statusCode(500);
		}
		finally {
			teardownOwnerAndPet(info);
		}
	}

	@Test
	@DisplayName("VTC_api_xss - name에 XSS 스크립트 -> sanitize 없이 그대로 저장 (200)")
	void VTC_api_xss(TestInfo info) {
