package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

/**
 * Black-Box API Integration Test
 *
 * @target-controller VetController
 * (src/main/java/org/springframework/samples/petclinic/vet/VetController.java)
 * @target-api GET /vets
 *
 * `showResourcesVetList()` is a plain @Controller method (not @RestController) but is annotated
 * @ResponseBody, so it serializes a `Vets` wrapper object ({"vetList": [...]}) directly as JSON,
 * with no view resolution involved.
 *
 * Auth: `/vets` does not match any of the `/api/**`/`/actuator/**`/etc. matchers in
 * SecurityConfig, so it falls through to `.anyRequest().permitAll()` - no Authorization header
 * required (confirmed via analyze-auth-flow and direct read of SecurityConfig.java).
 *
 * Data: this endpoint only reads vetRepository.findAll(); none of the 8 target endpoints in this
 * suite ever mutate the `vets`/`specialties`/`vet_specialties` tables, so the seed data from
 * src/main/resources/db/mysql/data.sql is stable for the lifetime of the whole run and can be
 * asserted exactly (no setup/teardown SQL needed - this is a pure read against fixed seed data).
 * Seed data used below:
 *   vets: (1,James,Carter) (2,Helen,Leary) (3,Linda,Douglas) (4,Rafael,Ortega) (5,Henry,Stevens) (6,Sharon,Jenkins)
 *   specialties: (1,radiology) (2,surgery) (3,dentistry)
 *   vet_specialties: (2,1) (3,2) (3,3) (4,2) (5,1)
 *   -> vet 2 (Helen Leary): [radiology]; vet 3 (Linda Douglas): [dentistry, surgery] (getSpecialties()
 *      sorts by NamedEntity::getName, so "dentistry" < "surgery" alphabetically); vet 4 (Rafael Ortega):
 *      [surgery]; vet 5 (Henry Stevens): [radiology]; vets 1 and 6 have no specialties.
 *
 * No outbound HTTP calls (detect-external-calls): no WireMock stubs required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class GetVetsPageBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/vets";

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_getVets_success - 전체 vet 목록 200, 총 6명, specialty 없는 vet 1(James Carter) 정확 매칭")
	void NTC_getVets_success() {
		given().log().all()
			.baseUri(BASE_URL)
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("vetList.size()", equalTo(6))
			.body("vetList.find { it.id == 1 }.firstName", equalTo("James"))
			.body("vetList.find { it.id == 1 }.lastName", equalTo("Carter"))
			.body("vetList.find { it.id == 1 }.specialties.size()", equalTo(0))
			.body("vetList.find { it.id == 1 }.nrOfSpecialties", equalTo(0));
	}

	@Test
	@DisplayName("NTC_getVets_success_singleSpecialty - vet 2(Helen Leary)는 정확히 1개의 specialty(radiology) 보유")
	void NTC_getVets_success_singleSpecialty() {
		given().log().all()
			.baseUri(BASE_URL)
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("vetList.find { it.id == 2 }.firstName", equalTo("Helen"))
			.body("vetList.find { it.id == 2 }.lastName", equalTo("Leary"))
			.body("vetList.find { it.id == 2 }.nrOfSpecialties", equalTo(1))
			.body("vetList.find { it.id == 2 }.specialties[0].name", equalTo("radiology"));
	}

	@Test
	@DisplayName("NTC_getVets_success_multipleSpecialtiesSortedAlphabetically - vet 3(Linda Douglas)의 specialties는 이름순 정렬")
	void NTC_getVets_success_multipleSpecialtiesSortedAlphabetically() {
		given().log().all()
			.baseUri(BASE_URL)
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("vetList.find { it.id == 3 }.firstName", equalTo("Linda"))
