package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.hasItems;

/**
 * Black-Box API Integration Test
 *
 * @target-controller VetRestController
 * (src/main/java/org/springframework/samples/petclinic/vet/VetRestController.java)
 * @target-api GET /api/vets
 *
 * Auth: /api/** requires a valid JWT (SecurityConfig). Token obtained via real
 * POST /api/auth/login (admin/password).
 *
 * getAllVets() logic (read directly from source):
 * - `specialty` is an optional @RequestParam(required = false) String.
 * - if present and non-empty, filters vets whose specialties (any) contain the given substring,
 *   case-insensitively (`spec.getName().toLowerCase().contains(specialty.toLowerCase())`).
 * - returns Collection<Vet> directly (no wrapper object, unlike GET /vets's Vets.vetList) - the
 *   JSON response body is a bare array.
 * - no match -> empty array with 200 (not 404); this is a filter, not a lookup-by-id.
 *
 * Data: read-only against the stable seed data (see GetVetsPageBlackBoxTest for the full seed
 * dump); no setup/teardown SQL needed.
 *
 * No outbound HTTP calls (detect-external-calls): no WireMock stubs required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class GetApiVetsBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/api/vets";

	private static String obtainAdminToken() {
		return given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_getAllVets_success_noFilter - specialty 파라미터 없이 전체 6명 조회 (200)")
	void NTC_getAllVets_success_noFilter() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("size()", equalTo(6))
			.body("id", hasItems(1, 2, 3, 4, 5, 6))
			.body("find { it.id == 1 }.firstName", equalTo("James"))
			.body("find { it.id == 1 }.lastName", equalTo("Carter"));
	}

	@Test
	@DisplayName("NTC_getAllVets_filterBySpecialty_surgery - specialty=surgery -> vet 3, 4만 매칭 (200)")
	void NTC_getAllVets_filterBySpecialty_surgery() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
			.queryParam("specialty", "surgery")
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("size()", equalTo(2))
			.body("id", hasItems(3, 4))
			.body("find { it.id == 3 }.lastName", equalTo("Douglas"))
			.body("find { it.id == 4 }.lastName", equalTo("Ortega"));
	}

	@Test
	@DisplayName("NTC_getAllVets_filterBySpecialty_caseInsensitiveSubstring - specialty=RADIO(대문자,부분일치) -> vet 2,5 매칭 (200)")
	void NTC_getAllVets_filterBySpecialty_caseInsensitiveSubstring() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
			.queryParam("specialty", "RADIO")
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("size()", equalTo(2))
			.body("id", hasItems(2, 5))
			.body("find { it.id == 2 }.lastName", equalTo("Leary"))
			.body("find { it.id == 5 }.lastName", equalTo("Stevens"));
	}

	// ===================== ATC =====================

	@Test
	@DisplayName("ATC_specialty_noMatch - 존재하지 않는 specialty -> 빈 배열(200), 404 아님")
	void ATC_specialty_noMatch() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
			.queryParam("specialty", "nonexistent_specialty_xyz")
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("size()", equalTo(0));
	}

	@Test
	@DisplayName("ATC_code400 - URL에 잘못된 percent-encoding 전송 -> 서블릿 컨테이너의 URI 디코딩 실패 -> 400")
	void ATC_code400() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH + "?bad=%zz")
		.then().log().all()
			.statusCode(400);
	}

	// ===================== VTC (specialty query-param mutations) =====================

	@Test
	@DisplayName("VTC_specialty_EMPTY - specialty=\"\" -> 빈 문자열은 필터 미적용 조건과 동일 -> 전체 6명 (200)")
	void VTC_specialty_EMPTY() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
			.queryParam("specialty", "")
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("size()", equalTo(6));
	}

	@Test
	@DisplayName("VTC_specialty_SPECIAL_CHAR - SQL injection 문자열 -> 단순 contains() 비교이므로 매칭 없이 빈 배열 (200)")
	void VTC_specialty_SPECIAL_CHAR() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
			.queryParam("specialty", "'; DROP TABLE vets--")
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(200)
			.body("size()", equalTo(0));
	}

	// ===================== API-level VTC =====================

	@Test
	@DisplayName("VTC_api_wrongMethod - 잘못된 HTTP 메서드(POST) -> 405 Method Not Allowed")
	void VTC_api_wrongMethod() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(405);
	}

	// ===================== Auth =====================

	@Test
	@DisplayName("ATC_noAuthHeader - Authorization 헤더 없이 호출 -> 403 Forbidden")
	void ATC_noAuthHeader() {
		given().log().all()
			.baseUri(BASE_URL)
			.accept(ContentType.JSON)
		.when()
			.get(API_PATH)
		.then().log().all()
			.statusCode(403);
	}

}

