package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

/**
 * Black-Box API Integration Test
 *
 * @target-controller VetRestController
 * (src/main/java/org/springframework/samples/petclinic/vet/VetRestController.java)
 * @target-api GET /api/vets/{vetId}
 *
 * Auth: /api/** requires a valid JWT. Token obtained via real POST /api/auth/login.
 *
 * getVet() logic (read directly from source):
 *   return vetRepository.findAll().stream().filter(vet -> vet.getId().equals(vetId)).findFirst().orElse(null);
 * The method's return type is plain `Vet` (not Optional/ResponseEntity). When no vet matches,
 * this returns Java `null` directly from a @RestController handler. Spring MVC's message-converter
 * write path for a null return value simply writes an empty body and leaves the response status at
 * its default (200 OK) - there is no 404 here, unlike OwnerRestController.getOwner or
 * PetRestController.createPet which explicitly build ResponseEntity.notFound(). This is a
 * deliberately verified (not assumed) distinction between this endpoint and the others in the suite.
 *
 * Data: read-only against the stable seed data (see GetVetsPageBlackBoxTest for the full seed
 * dump); no setup/teardown SQL needed.
 *
 * No outbound HTTP calls (detect-external-calls): no WireMock stubs required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class GetApiVetsByIdBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static String obtainAdminToken() {
		return given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	@DisplayName("NTC_getVet_success_vetWithoutSpecialty - vet 1(James Carter, specialty 없음) 정확 매칭 (200)")
	void NTC_getVet_success_vetWithoutSpecialty() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/1")
		.then().log().all()
			.statusCode(200)
			.body("id", equalTo(1))
			.body("firstName", equalTo("James"))
			.body("lastName", equalTo("Carter"))
			.body("specialties.size()", equalTo(0));
	}

	@Test
	@DisplayName("NTC_getVet_success_vetWithSingleSpecialty - vet 4(Rafael Ortega, surgery) 정확 매칭 (200)")
	void NTC_getVet_success_vetWithSingleSpecialty() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/4")
		.then().log().all()
			.statusCode(200)
			.body("id", equalTo(4))
			.body("firstName", equalTo("Rafael"))
			.body("lastName", equalTo("Ortega"))
			.body("specialties.size()", equalTo(1))
			.body("specialties[0].name", equalTo("surgery"));
	}

	@Test
	@DisplayName("NTC_getVet_success_vetWithMultipleSpecialties - vet 3(Linda Douglas, dentistry+surgery) 정확 매칭 (200)")
	void NTC_getVet_success_vetWithMultipleSpecialties() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/3")
		.then().log().all()
			.statusCode(200)
			.body("id", equalTo(3))
			.body("firstName", equalTo("Linda"))
			.body("lastName", equalTo("Douglas"))
			.body("specialties.size()", equalTo(2))
			.body("specialties[0].name", equalTo("dentistry"))
			.body("specialties[1].name", equalTo("surgery"));
	}

	// ===================== ATC (business exception) =====================

	@Test
	@DisplayName("ATC_vetId_noData - 존재하지 않는 vetId -> orElse(null) -> 200 OK + 빈 body (404 아님)")
	void ATC_vetId_noData() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/999999")
		.then().log().all()
			.statusCode(200)
			.body(equalTo(""));
	}

	@Test
	@DisplayName("ATC_code400 - URL에 잘못된 percent-encoding 전송 -> 서블릿 컨테이너의 URI 디코딩 실패 -> 400")
	void ATC_code400() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/1?bad=%zz")
		.then().log().all()
			.statusCode(400);
	}

	// ===================== VTC (vetId path-variable mutations) =====================

	@Test
	@DisplayName("VTC_vetId_INVALID_FORMAT - vetId=\"abc\" (숫자 아님) -> MethodArgumentTypeMismatchException -> 400")
	void VTC_vetId_INVALID_FORMAT() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/abc")
		.then().log().all()
			.statusCode(400);
	}

	@Test
	@DisplayName("VTC_vetId_SPECIAL_CHAR - vetId에 SQL injection 문자열 -> 경로 세그먼트 타입 변환 실패 -> 400")
	void VTC_vetId_SPECIAL_CHAR() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/1%3B%20DROP%20TABLE%20vets--")
		.then().log().all()
			.statusCode(400);
	}

	// ===================== API-level VTC =====================

	@Test
	@DisplayName("VTC_api_wrongMethod - 잘못된 HTTP 메서드(POST) -> 405 Method Not Allowed")
	void VTC_api_wrongMethod() {
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + obtainAdminToken())
			.accept(ContentType.JSON)
		.when()
			.post("/api/vets/1")
		.then().log().all()
			.statusCode(405);
	}

	// ===================== Auth =====================

	@Test
	@DisplayName("ATC_noAuthHeader - Authorization 헤더 없이 호출 -> 403 Forbidden")
	void ATC_noAuthHeader() {
		given().log().all()
			.baseUri(BASE_URL)
			.accept(ContentType.JSON)
		.when()
			.get("/api/vets/1")
		.then().log().all()
			.statusCode(403);
	}

}

